INSERT INTO "messages" ('id', 'folder_id', 'message_id', 'subject', 'from_addr', 'to_addr_json', 'cc_addr_json', 'bcc_addr_json', 'date', 'body_text', 'body_html', 'is_read', 'is_important', 'is_flagged', 'in_reply_to', 'references_header', 'headers_json', 'uid', 'size', 'created_at') VALUES (539, 1, '<viuhtunmn3v7sx3l5yv@workshop-mail.example>', 'Kitchen shared-equipment wording', 'food.safety@example.com', '["ops-assistant@example.com"]', '[]', '[]', '2026-02-21T09:52:00Z', 'The label says “prepared in a shared kitchen” rather than promising absence of cross-contact. Participants can opt out of the meal.', NULL, 0, 0, 0, NULL, NULL, '{}', 18163, 255, '2026-02-21T09:52:00Z');
INSERT INTO "messages" ('id', 'folder_id', 'message_id', 'subject', 'from_addr', 'to_addr_json', 'cc_addr_json', 'bcc_addr_json', 'date', 'body_text', 'body_html', 'is_read', 'is_important', 'is_flagged', 'in_reply_to', 'references_header', 'headers_json', 'uid', 'size', 'created_at') VALUES (540, 1, '<20260311.fhcapboud5lvk3pdxe@ops-letter.example>', 'Tax invoice legal-name mismatch', 'tax.controls@example.com', '["ops-assistant@example.com"]', '[]', '[]', '2026-03-11T10:24:00Z', 'A workshop vendor used its studio brand on the invoice while the contract named the operating company. Accounts Payable returned it for correction.', NULL, 1, 0, 0, NULL, NULL, '{}', 18180, 267, '2026-03-11T10:24:00Z');
INSERT INTO "messages" ('id', 'folder_id', 'message_id', 'subject', 'from_addr', 'to_addr_json', 'cc_addr_json', 'bcc_addr_json', 'date', 'body_text', 'body_html', 'is_read', 'is_important', 'is_flagged', 'in_reply_to', 'references_header', 'headers_json', 'uid', 'size', 'created_at') VALUES (541, 1, '<b3r6qmt.7dgnrf3sotza@learning-post.example>', 'Optional spoken report confirmed', 'people.experience@example.com', '["ops-assistant@example.com"]', '[]', '[]', '2026-06-12T08:11:00Z', 'Participants could submit paired notes without speaking to the full room. Facilitators did not ask why someone skipped the report.', NULL, 0, 0, 0, NULL, NULL, '{}', 18197, 250, '2026-06-12T08:11:00Z');
